function refId(v) { return Array.isArray(v) ? v[1] : v; }
const cfg = $('Set Config').first().json;
const users = $('Get Users').all().map((i) => i.json).filter((r) => r.id != null);
const user = users.find((u) => u.id === cfg.userId);
if (!user) return [{ json: { ...cfg, ok: false, error: 'unknown_user' } }];

const configRow = $('Get Config').all().map((i) => i.json).find((r) => r.id != null);
const MAX_ENERGY = (configRow && configRow.DigMaxEnergy) || 5;
const REGEN_SECONDS = (configRow && configRow.DigRegenSeconds) || 60;
const BOARD_SIZE = 16;
// Empreintes de tresors : la plupart tiennent sur 1 tuile, mais certaines
// (surtout les cartes, plus rares) sont etalees sur plusieurs tuiles - il
// faut alors creuser TOUTES ses tuiles pour liberer l'objet. Table enrichie
// (2026-09-29) : ajout d'une empreinte "carte Rare" (3 cases, entre le
// booster et la carte Commune en valeur) a la place d'une des 3 poussieres
// simples, pour varier les recompenses sans trop densifier le plateau.
const TREASURE_SHAPES = [
  { cells: 4, reward: 'card' },
  { cells: 3, reward: 'rareCard' },
  { cells: 2, reward: 'booster' },
  { cells: 2, reward: 'bigDust' },
  { cells: 1, reward: 'smallDust' },
  { cells: 1, reward: 'smallDust' }
];

function generateBoard() {
  const order = Array.from({ length: BOARD_SIZE }, (_, i) => i);
  for (let i = order.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = order[i]; order[i] = order[j]; order[j] = tmp;
  }
  const tiles = Array.from({ length: BOARD_SIZE }, () => ({ t: null, d: false }));
  const treasures = [];
  let cursor = 0;
  TREASURE_SHAPES.forEach((shape) => {
    const treasureIndex = treasures.length;
    treasures.push({ cells: shape.cells, dug: 0, reward: shape.reward, done: false });
    for (let i = 0; i < shape.cells; i++) {
      tiles[order[cursor]].t = treasureIndex;
      cursor++;
    }
  });
  return { tiles, treasures };
}

// Grille terminee des que TOUS les tresors sont trouves (2026-10-04) : plus
// besoin de creuser les tuiles vides restantes, une nouvelle grille arrive
// tout de suite (fouille du joueur comme du chien).
function allTreasuresFound(b) { return b.treasures.every((tr) => tr.done) || b.tiles.every((t) => t.d); }

const now = Math.floor(Date.now() / 1000);
const storedEnergy = user.DigEnergy != null ? user.DigEnergy : MAX_ENERGY;
const lastAt = user.LastDigEnergyAt || now;
let currentEnergy = storedEnergy;
let secondsUntilNext = null;
if (storedEnergy < MAX_ENERGY) {
  const elapsed = Math.max(0, now - lastAt);
  const gained = Math.floor(elapsed / REGEN_SECONDS);
  currentEnergy = Math.min(MAX_ENERGY, storedEnergy + gained);
  if (currentEnergy < MAX_ENERGY) secondsUntilNext = REGEN_SECONDS - (elapsed % REGEN_SECONDS);
}

let board = null;
try { board = user.DigBoardState ? JSON.parse(user.DigBoardState) : null; } catch (e) { board = null; }
let boardDirty = false;
if (!board || !Array.isArray(board.tiles) || board.tiles.length !== BOARD_SIZE || !Array.isArray(board.treasures)) {
  board = generateBoard();
  boardDirty = true;
}

// ---------------------------------------------------------------------
// Chien de fouille (2026-10-02) : un os (achete contre des poussieres, ou
// laisse par un sacrifice rate a l'autel) envoie un chien creuser a la place
// du joueur pendant DOG_DURATION, une tuile toutes les DOG_INTERVAL, sans
// energie. Rattrapage "paresseux" : les tuiles dues depuis DogLastDigAt sont
// creusees a chaque appel (statut ou fouille). Une carte trouvee par le chien
// est rapportee sous forme de poussieres (une seule ligne Pulls creee par
// execution dans ce workflow). Colonnes requises : Users.BoneCount,
// Users.DogUntil, Users.DogLastDigAt.
// ---------------------------------------------------------------------
// Chien plus utile (2026-10-04) : 1 tuile toutes les 5 min (24 par os au
// lieu de 12), du FLAIR (il termine d'abord les tresors entames, puis vise
// une tuile a tresor 2 fois sur 3), il rapporte les VRAIES cartes trouvees
// (lignes Pulls creees par le noeud "Create Dog Pulls", numero de serie
// inclus) au lieu de poussieres, les os se cumulent (+2h par os, jusqu'a
// 12h d'avance) et, tant qu'il est actif, il signale au joueur une tuile qui
// cache un tresor (sniffTile).
const BONE_COST = (configRow && configRow.DogBoneCost) || 150;
const DOG_DURATION = 2 * 3600;
const DOG_INTERVAL = 300;
const DOG_MAX_AHEAD = 12 * 3600;
const DOG_TREASURE_FLAIR = 0.66;
const allPulls = $('Get Pulls').all().map((i) => i.json).filter((r) => r.id != null);
const allCards = $('Get Cards').all().map((i) => i.json).filter((r) => r.id != null);
const allRarities = $('Get Rarities').all().map((i) => i.json).filter((r) => r.id != null);
const usedSerials = {};
allPulls.forEach((p) => { const cid = refId(p.Card); if (!usedSerials[cid]) usedSerials[cid] = new Set(); if (p.SerialNumber != null) usedSerials[cid].add(p.SerialNumber); });
function nextSerialFor(cid) { const used = usedSerials[cid]; for (let n = 1; ; n++) { if (!used || !used.has(n)) { if (!usedSerials[cid]) usedSerials[cid] = new Set(); usedSerials[cid].add(n); return n; } } }
const tiersByRarity = allRarities.filter((r) => r.SortOrder != null).sort((a, b) => (a.SortOrder || 0) - (b.SortOrder || 0));
// Tire une carte du palier voulu (0 = Commune, 1 = Rare) et lui reserve un
// numero de serie ; null si aucune carte disponible a ce palier.
function drawCard(reward) {
  const targetRarity = tiersByRarity[reward === 'rareCard' ? 1 : 0] || tiersByRarity[0];
  const candidates = allCards.filter((c) => c.Active !== false && !c.IsPromo && targetRarity && refId(c.Rarity) === targetRarity.id);
  if (!candidates.length) return null;
  const picked = candidates[Math.floor(Math.random() * candidates.length)];
  return { cardId: picked.id, name: picked.Name, serialNumber: nextSerialFor(picked.id),
    rarity: { id: targetRarity.id, name: targetRarity.Name, key: targetRarity.Key, colorHex: targetRarity.ColorHex } };
}
function dogPickTile() {
  const undug = board.tiles.map((t, i) => (t.d ? null : i)).filter((i) => i != null);
  const started = undug.filter((i) => { const t = board.tiles[i]; return t.t != null && board.treasures[t.t].dug > 0; });
  if (started.length) return started[Math.floor(Math.random() * started.length)];
  const withTreasure = undug.filter((i) => board.tiles[i].t != null);
  if (withTreasure.length && Math.random() < DOG_TREASURE_FLAIR) return withTreasure[Math.floor(Math.random() * withTreasure.length)];
  return undug[Math.floor(Math.random() * undug.length)];
}
let bones = user.BoneCount || 0;
let dogUntil = user.DogUntil || 0;
let dogLast = user.DogLastDigAt || 0;
const dogReport = { tiles: 0, dust: 0, boosters: 0, keys: 0, cards: [] };
let userDirty = false;
if (dogUntil > dogLast) {
  let steps = Math.floor((Math.min(now, dogUntil) - dogLast) / DOG_INTERVAL);
  while (steps-- > 0) {
    if (allTreasuresFound(board)) board = generateBoard();
    const tile = board.tiles[dogPickTile()];
    tile.d = true;
    if (tile.t != null) {
      const tr = board.treasures[tile.t];
      tr.dug++;
      if (tr.dug >= tr.cells) {
        tr.done = true;
        if (tr.reward === 'smallDust') dogReport.dust += 5 + Math.floor(Math.random() * 11);
        else if (tr.reward === 'bigDust') dogReport.dust += 25 + Math.floor(Math.random() * 26);
        else if (tr.reward === 'booster') dogReport.boosters += 1;
        else {
          const card = drawCard(tr.reward);
          if (card) dogReport.cards.push(card);
          else dogReport.dust += tr.reward === 'rareCard' ? 50 : 30;
        }
      }
    }
    if (Math.random() < 0.02) dogReport.keys += 1;
    dogReport.tiles++;
    dogLast += DOG_INTERVAL;
  }
  if (now >= dogUntil) dogLast = dogUntil;
  if (dogReport.tiles > 0 || now >= dogUntil) {
    userDirty = true;
    boardDirty = true;
    user.StardustCount = (user.StardustCount || 0) + dogReport.dust;
    user.BoosterCount = (user.BoosterCount || 0) + dogReport.boosters;
    user.KeyCount = (user.KeyCount || 0) + dogReport.keys;
  }
}
// Tous les tresors trouves (par le chien, ou plateau d'avant ce changement
// reste en attente) : un nouveau plateau, pour la suite.
if (allTreasuresFound(board)) { board = generateBoard(); boardDirty = true; }
// Flair : tant que le chien est actif, il montre au joueur une tuile qui
// cache un tresor (de preference un tresor deja entame).
function sniffTile() {
  if (dogUntil <= now) return null;
  const undug = board.tiles.map((t, i) => (t.d ? null : i)).filter((i) => i != null && board.tiles[i].t != null);
  if (!undug.length) return null;
  const started = undug.filter((i) => board.treasures[board.tiles[i].t].dug > 0);
  return (started.length ? started : undug)[0];
}
const dogFields = () => ({ newBoneCount: bones, newDogUntil: dogUntil, newDogLast: dogLast, dogReport, boneCost: BONE_COST,
  dogCards: dogReport.cards, sniffTile: sniffTile(), dogInterval: DOG_INTERVAL });

if (cfg.action === 'buyBone') {
  if ((user.StardustCount || 0) < BONE_COST) return [{ json: { ...cfg, ok: false, error: 'not_enough_dust' } }];
  user.StardustCount -= BONE_COST;
  bones += 1;
  userDirty = true;
}
if (cfg.action === 'useBone') {
  if (bones < 1) return [{ json: { ...cfg, ok: false, error: 'no_bone' } }];
  // Os cumulables : si le chien creuse deja, l'os prolonge sa sortie de 2h
  // (dans la limite de DOG_MAX_AHEAD d'avance).
  if (dogUntil > now) {
    if (dogUntil + DOG_DURATION - now > DOG_MAX_AHEAD) return [{ json: { ...cfg, ok: false, error: 'dog_max_time' } }];
    bones -= 1;
    dogUntil += DOG_DURATION;
  } else {
    bones -= 1;
    dogUntil = now + DOG_DURATION;
    dogLast = now;
  }
  userDirty = true;
}

if (cfg.action === 'dig') {
  if (currentEnergy < 1) return [{ json: { ...cfg, ok: false, error: 'no_energy' } }];
  const tileIndex = Number(cfg.tileIndex);
  if (!Number.isInteger(tileIndex) || tileIndex < 0 || tileIndex >= BOARD_SIZE) {
    return [{ json: { ...cfg, ok: false, error: 'invalid_tile' } }];
  }
  const tile = board.tiles[tileIndex];
  if (tile.d) return [{ json: { ...cfg, ok: false, error: 'tile_already_dug' } }];

  const newEnergy = currentEnergy - 1;
  tile.d = true;
  // Ancre de regeneration (bug reel corrige 2026-10-01) : auparavant
  // LastDigEnergyAt etait remis a "maintenant" a chaque coup de pioche, ce
  // qui EFFACAIT la progression partielle vers le point suivant - creuser
  // un peu plus souvent que le delai de regen empechait toute recharge.
  // Si la jauge etait pleine, le compteur demarre maintenant ; sinon on
  // avance l'ancre seulement des points deja regeneres, le reste du delai
  // en cours est conserve.
  const elapsedSinceAnchor = Math.max(0, now - lastAt);
  const regenGained = storedEnergy < MAX_ENERGY ? Math.floor(elapsedSinceAnchor / REGEN_SECONDS) : 0;
  const newLastAt = currentEnergy >= MAX_ENERGY ? now : lastAt + regenGained * REGEN_SECONDS;
  const newSecondsUntilNext = REGEN_SECONDS - ((now - newLastAt) % REGEN_SECONDS);

  // Clef secrete : 2% de chance a CHAQUE creusage, independamment du tresor
  // de la tuile (meme une tuile deja liee a un tresor peut en faire gagner
  // une). Sert a debloquer la serrure cachee de la page Code (voir
  // unlock-secret.json) - remplace l'ancien Konami code.
  const foundKey = Math.random() < 0.02;

  let outcome = 'nothing', dustGained = 0, boosterGranted = false, revealed = false, remaining = 0;
  let cardId = null, serialNumber = null, cardName = null, cardRarity = null;

  if (tile.t != null) {
    const treasure = board.treasures[tile.t];
    treasure.dug++;
    if (treasure.dug >= treasure.cells) {
      treasure.done = true;
      revealed = true;
      if (treasure.reward === 'smallDust') { outcome = 'dust'; dustGained = 5 + Math.floor(Math.random() * 11); }
      else if (treasure.reward === 'bigDust') { outcome = 'dust'; dustGained = 25 + Math.floor(Math.random() * 26); }
      else if (treasure.reward === 'booster') { outcome = 'booster'; boosterGranted = true; }
      else if (treasure.reward === 'card' || treasure.reward === 'rareCard') {
        // Carte Commune (empreinte "card") ou Rare (empreinte "rareCard") :
        // meme logique de tirage/numerotation, seul le PALIER de rarete cible
        // change (index 0 = la plus basse SortOrder, index 1 = la suivante).
        // Meme tirage que le chien (drawCard) : les numeros de serie deja
        // reserves par le chien dans cette execution ne sont pas reutilises.
        const drawn = drawCard(treasure.reward);
        if (drawn) {
          cardId = drawn.cardId;
          cardName = drawn.name;
          cardRarity = drawn.rarity;
          serialNumber = drawn.serialNumber;
          outcome = 'card';
        } else {
          // Aucune carte de ce palier disponible (toutes epuisees ou aucune
          // active) : on degrade silencieusement vers de la poussiere plutot
          // que de faire echouer la fouille (le joueur a quand meme depense
          // son energie et libere les tuiles).
          outcome = 'dust';
          dustGained = treasure.reward === 'rareCard' ? 50 : 30;
        }
      }
    } else {
      outcome = 'partial';
      remaining = treasure.cells - treasure.dug;
    }
  }

  // Dernier tresor trouve : nouveau plateau tout de suite. La reponse montre
  // l'ancien plateau entierement retourne (tuiles vides incluses) le temps
  // que le joueur voie qu'il n'y avait plus rien.
  const boardCleared = allTreasuresFound(board);
  const finalBoard = boardCleared ? generateBoard() : board;
  if (boardCleared) board.tiles.forEach((t) => { t.d = true; });

  return [{ json: {
    ...cfg, ok: true, mutation: 'dig', boardDirty: true,
    newEnergy, newLastAt, secondsUntilNext: newSecondsUntilNext, regenSeconds: REGEN_SECONDS, maxEnergy: MAX_ENERGY,
    outcome, dustGained, boosterGranted, revealed, remaining, tileIndex, boardCleared,
    board: JSON.stringify(finalBoard),
    revealBoard: JSON.stringify(board),
    newStardust: (user.StardustCount || 0) + dustGained,
    newBoosterCount: (user.BoosterCount || 0) + (boosterGranted ? 1 : 0),
    foundKey, newKeyCount: (user.KeyCount || 0) + (foundKey ? 1 : 0),
    cardId, cardName, serialNumber, cardRarity,
    ...dogFields()
  } }];
}

// action === 'status' (ou toute autre valeur) : lecture seule pour l'energie,
// mais persiste un plateau tout juste genere (premiere visite du joueur, ou
// etat corrompu) pour qu'il reste stable au prochain appel.
return [{ json: {
  ...cfg, ok: true, mutation: userDirty ? 'user' : 'none', boardDirty, userDirty,
  newStardust: user.StardustCount || 0, newBoosterCount: user.BoosterCount || 0, newKeyCount: user.KeyCount || 0,
  ...dogFields(),
  energy: currentEnergy, maxEnergy: MAX_ENERGY, secondsUntilNext, regenSeconds: REGEN_SECONDS,
  board: JSON.stringify(board),
  revealBoard: JSON.stringify(board)
} }];

const d = $('Dispatch Action').first().json;
const board = JSON.parse(d.revealBoard);
const tiles = board.tiles.map((t) => {
  if (!t.d) return { dug: false };
  if (t.t == null) return { dug: true, treasure: null };
  const tr = board.treasures[t.t];
  return { dug: true, treasure: tr.done ? { reward: tr.reward, done: true } : { reward: tr.reward, done: false, remaining: tr.cells - tr.dug } };
});
return [{ json: {
  dug: true,
  tileIndex: d.tileIndex,
  outcome: d.outcome,
  revealed: d.revealed,
  remaining: d.remaining,
  dustGained: d.dustGained || 0,
  boosterGranted: d.boosterGranted || false,
  foundKey: d.foundKey || false,
  card: d.outcome === 'card' ? { cardId: d.cardId, name: d.cardName, serialNumber: d.serialNumber, rarity: d.cardRarity } : null,
  newEnergy: d.newEnergy,
  maxEnergy: d.maxEnergy,
  secondsUntilNext: d.secondsUntilNext,
  regenSeconds: d.regenSeconds,
  bones: d.newBoneCount || 0,
  dogSecondsLeft: Math.max(0, (d.newDogUntil || 0) - Math.floor(Date.now() / 1000)),
  dogReport: d.dogReport || null,
  sniffTile: d.sniffTile != null ? d.sniffTile : null,
  dogInterval: d.dogInterval,
  boardCleared: d.boardCleared,
  tiles
} }];

const d = $('Dispatch Action').first().json;
const board = JSON.parse(d.revealBoard);
const tiles = board.tiles.map((t) => {
  if (!t.d) return { dug: false };
  if (t.t == null) return { dug: true, treasure: null };
  const tr = board.treasures[t.t];
  return { dug: true, treasure: tr.done ? { reward: tr.reward, done: true } : { reward: tr.reward, done: false, remaining: tr.cells - tr.dug } };
});
const nowS = Math.floor(Date.now() / 1000);
return [{ json: { energy: d.energy, maxEnergy: d.maxEnergy, secondsUntilNext: d.secondsUntilNext, regenSeconds: d.regenSeconds, tiles,
  bones: d.newBoneCount || 0, boneCost: d.boneCost, dogSecondsLeft: Math.max(0, (d.newDogUntil || 0) - nowS), dogReport: d.dogReport || null,
  sniffTile: d.sniffTile != null ? d.sniffTile : null, dogInterval: d.dogInterval,
  stardust: d.newStardust } }];

// Une ligne par carte rapportee par le chien (ou un seul item "skip").
const d = $('Dispatch Action').first().json;
const cards = d.dogCards || [];
if (!cards.length) return [{ json: { skip: true } }];
return cards.map((c) => ({ json: { skip: false, docId: d.docId, userId: d.userId, cardId: c.cardId, serialNumber: c.serialNumber } }));
